package com.codepilot1c.core.tools.development;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import com.google.gson.Gson;
import com.codepilot1c.core.tools.*;
import com.codepilot1c.core.edt.infobase.*;
import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;
import com.codepilot1c.core.mcp.host.*;

@ToolMeta(name="edt_update_control",category="qa",mutating=true,tags={"workspace","edt","sensitive"})
public final class EdtUpdateControlTool extends AbstractTool {
 public String getDescription(){return "Continue the ORIGINAL Bridge-owned native update/question, never launch another load. list(project), status(update_id); retry/cancel/update_and_launch/update_dynamic require fresh expected_question_sha256. update_dynamic is an explicit ONE-TIME authorized choice, only if the native exclusive-access dialog offers an enabled dynamic button; The platform decides whether changes support dynamic application; FULL still must pass native EQUAL verification. A user task explicitly authorizing 'do everything, update and launch' for this project/base may authorize these once commands without repeated questions; do not turn a task instruction into a permanent grant. For an explicitly requested persistent permission: policy_status(project), policy_preview(project,policy=allow_dynamic|ask), policy_apply(same args,expected_plan_sha256). Exact project path/branch context/base UUID/target are bound; ask revokes future auto-answers, never rolls back an already applied update. policy_revoke_preview(policy_id) -> policy_revoke(policy_id,expected_plan_sha256) revokes a saved permission even after unbind/branch change, without querying a database. apply allow_dynamic may answer CURRENT pending owned questions and future matching ones; it never starts a new update. Revalidate policy/exposure/binding at answer. No generic dialogs/security/trust automation or user-process termination. close_owned_and_retry additionally requires owner ui_run_id and fresh expected_cleanup_sha256; existing UI ownership/unknown guards remain. Save original job/update IDs; inspect platform result/EQUAL separately. Dynamic selection does not prove existing runtime clients reloaded configuration; no blind retry after unknown outcome.";}
 public String getParameterSchema(){return """
 {"type":"object","additionalProperties":false,"required":["action"],"properties":{"action":{"enum":["list","status","retry","cancel","update_and_launch","update_dynamic","close_owned_and_retry","policy_status","policy_preview","policy_apply","policy_revoke_preview","policy_revoke"]},"project":{"type":"string"},"update_id":{"type":"string","pattern":"^upd-[a-f0-9-]{36}$"},"expected_question_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"ui_run_id":{"type":"string"},"expected_cleanup_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"policy_id":{"type":"string","pattern":"^dynamic-[a-f0-9]{64}$"},"policy":{"enum":["ask","allow_dynamic"]},"expected_plan_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}}}
 """;}
 private static void requireUpdate(){var config=McpHostConfigStore.getInstance().load();if(config.getMutationPolicy()!=McpHostConfig.MutationPolicy.ALLOW||!new DefaultMcpToolExposurePolicy(config).isExposed("edt_infobase_refresh"))throw new IllegalStateException("Database update operation not allowed");}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){try{
  String action=p.requireString("action");var keys=new HashSet<>(p.getRaw().keySet());keys.remove("action");
  Set<String> fields=switch(action){case "list","policy_status"->Set.of("project");case "status"->Set.of("update_id");case "retry","cancel","update_and_launch","update_dynamic"->Set.of("update_id","expected_question_sha256");case "close_owned_and_retry"->Set.of("update_id","expected_question_sha256","ui_run_id","expected_cleanup_sha256");case "policy_revoke_preview"->Set.of("policy_id");case "policy_revoke"->Set.of("policy_id","expected_plan_sha256");case "policy_preview"->Set.of("project","policy");case "policy_apply"->Set.of("project","policy","expected_plan_sha256");default->throw new IllegalArgumentException("Unknown action");};
  if(!keys.equals(fields))throw new IllegalArgumentException("Exact action fields required");
  if(Set.of("list","status","policy_status","policy_preview","policy_revoke_preview").contains(action))return CompletableFuture.supplyAsync(()->{try{Object result=switch(action){case "list"->NativeUpdateInteraction.list(p.requireString("project"));case "status"->NativeUpdateInteraction.status(p.requireString("update_id"));case "policy_status"->DynamicUpdatePolicy.workspace().status(p.requireString("project"));case "policy_revoke_preview"->DynamicUpdatePolicy.workspace().revokePreview(p.requireString("policy_id"));default->DynamicUpdatePolicy.workspace().preview(p.requireString("project"),p.requireString("policy"));};return ToolResult.success(new Gson().toJson(result));}catch(Exception error){return ToolResult.failure(error.getMessage());}});
  if(Set.of("update_and_launch","update_dynamic").contains(action)||(action.equals("policy_apply")&&"allow_dynamic".equals(p.requireString("policy"))))requireUpdate();
  if(action.equals("close_owned_and_retry")){var policy=new DefaultMcpToolExposurePolicy(McpHostConfigStore.getInstance().load());for(String tool:com.codepilot1c.core.edt.development.UiRunBackend.dependencies())if(!policy.isExposed(tool))throw new IllegalStateException("Owned UI cleanup dependency unavailable");if(!policy.isExposed("edt_ui_run"))throw new IllegalStateException("Owned UI cleanup unavailable");}
  String job=BackgroundJobRegistry.getInstance().startJob("update-wait-control",()->{
   Object result;
   if(action.equals("policy_revoke"))result=DynamicUpdatePolicy.workspace().revoke(p.requireString("policy_id"),p.requireString("expected_plan_sha256"));
   else if(action.equals("policy_apply")){String project=p.requireString("project");String policy=p.requireString("policy");if(policy.equals("allow_dynamic"))requireUpdate();var record=new LinkedHashMap<>(DynamicUpdatePolicy.workspace().apply(project,policy,p.requireString("expected_plan_sha256")));record.put("pending_answers",policy.equals("allow_dynamic")?NativeUpdateInteraction.applyPersistentToPending(project):List.of());result=record;}
   else if(action.equals("close_owned_and_retry"))result=NativeUpdateInteraction.closeOwnedAndRetry(p.requireString("update_id"),p.requireString("expected_question_sha256"),p.requireString("ui_run_id"),p.requireString("expected_cleanup_sha256"));
   else result=NativeUpdateInteraction.answer(p.requireString("update_id"),p.requireString("expected_question_sha256"),action);
   return new Gson().toJson(result);
  });
  return CompletableFuture.completedFuture(ToolResult.success(new Gson().toJson(Map.of("job_id",job,"next_tool","edt_operation_status","new_update_dispatched",false))));
 }catch(Exception error){return CompletableFuture.completedFuture(ToolResult.failure("EDT_UPDATE_CONTROL: "+error.getMessage()));}}
}
